public record Montant(decimal Valeur, string Devise)
{
    public Montant Ajouter(Montant autre) =>
        autre.Devise == Devise
            ? this with { Valeur = Valeur + autre.Valeur }
            : throw new InvalidOperationException("Devises différentes");
}

